317: 			case strings.HasPrefix(r.Stdout, "Amazon Linux 2"), strings.HasPrefix(r.Stdout, "Amazon Linux release 2"):
318: 				// Amazon Linux 2 (Karoo)
319: 				// Amazon Linux release 2 (Karoo)
320: 				release = "2"
321: 			default:
322: 				fields := strings.Fields(r.Stdout)
323: 				if len(fields) == 5 {
324: 					release = fields[4]
325: 				}
326: 			}
327: 		}
328: 		amazon := newAmazon(c)
329: 		amazon.setDistro(family, release)
330: 		return true, amazon
331: 	}
332: 
333: 	logging.Log.Debugf("Not RedHat like Linux. servername: %s", c.ServerName)
334: 	return false, &unknown{}
335: }
