418: func (o *redhatBase) scanPackages() (err error) {
419: 	o.log.Infof("Scanning OS pkg in %s", o.getServerInfo().Mode)
420: 	o.Packages, err = o.scanInstalledPackages()
421: 	if err != nil {
422: 		return xerrors.Errorf("Failed to scan installed packages: %w", err)
423: 	}
424: 
425: 	fn := func(pkgName string) execResult { return o.exec(fmt.Sprintf("rpm -q --last %s", pkgName), noSudo) }
426: 	o.Kernel.RebootRequired, err = o.rebootRequired(fn)
427: 	if err != nil {
