429: 		o.log.Warnf("err: %+v", err)
430: 		o.warns = append(o.warns, err)
431: 		// Only warning this error
432: 	}
433: 
434: 	if o.getServerInfo().Mode.IsOffline() || (o.Distro.Family == constant.RedHat && o.getServerInfo().Mode.IsFast()) {
435: 		return nil
436: 	}
