441: 		o.log.Warnf("err: %+v", err)
442: 		o.warns = append(o.warns, err)
443: 		// Only warning this error
444: 	} else {
445: 		o.Packages.MergeNewVersion(updatable)
446: 	}
447: 	return nil
448: }
