450: func (o *redhatBase) rebootRequired(fn func(s string) execResult) (bool, error) {
451: 	pkgName := "kernel"
452: 	if strings.Contains(o.Kernel.Release, "uek.") {
453: 		pkgName = "kernel-uek"
454: 	}
455: 
456: 	r := fn(pkgName)
457: 	scanner := bufio.NewScanner(strings.NewReader(r.Stdout))
458: 	if !r.isSuccess(0, 1) {
459: 		return false, xerrors.Errorf("Failed to detect the last installed kernel : %v", r)
460: 	}
461: 	if !r.isSuccess() || !scanner.Scan() {
462: 		return false, nil
463: 	}
464: 	lastInstalledKernelVer := strings.Fields(scanner.Text())[0]
465: 	running := fmt.Sprintf("%s-%s", pkgName, o.Kernel.Release)
466: 	return running != lastInstalledKernelVer, nil
467: }
