469: func (o *redhatBase) scanInstalledPackages() (models.Packages, error) {
470: 	release, version, err := o.runningKernel()
471: 	if err != nil {
472: 		return nil, err
473: 	}
474: 	o.Kernel = models.Kernel{
475: 		Release: release,
476: 		Version: version,
477: 	}
478: 
479: 	var r execResult
480: 	switch o.getDistro().Family {
481: 	case constant.Amazon:
482: 		switch strings.Fields(o.getDistro().Release)[0] {
483: 		case "2":
484: 			if o.exec("rpm -q yum-utils", noSudo).isSuccess() {
485: 				r = o.exec("repoquery --all --pkgnarrow=installed --qf='%{NAME} %{EPOCH} %{VERSION} %{RELEASE} %{ARCH} %{UI_FROM_REPO}'", o.sudo.repoquery())
486: 			} else {
487: 				r = o.exec(o.rpmQa(), noSudo)
488: 			}
489: 		default:
490: 			r = o.exec(o.rpmQa(), noSudo)
491: 		}
492: 	default:
493: 		r = o.exec(o.rpmQa(), noSudo)
494: 	}
495: 	if !r.isSuccess() {
496: 		return nil, xerrors.Errorf("Scan packages failed: %s", r)
497: 	}
498: 	installed, _, err := o.parseInstalledPackages(r.Stdout)
499: 	if err != nil {
500: 		return nil, xerrors.Errorf("Failed to parse installed packages. err: %w", err)
501: 	}
502: 	return installed, nil
503: }
