568: func (o *redhatBase) parseInstalledPackagesLine(line string) (*models.Package, error) {
569: 	fields := strings.Fields(line)
570: 	if len(fields) < 5 {
571: 		return nil, xerrors.Errorf("Failed to parse package line: %s", line)
572: 	}
573: 
574: 	ver := ""
575: 	epoch := fields[1]
576: 	if epoch == "0" || epoch == "(none)" {
577: 		ver = fields[2]
578: 	} else {
579: 		ver = fmt.Sprintf("%s:%s", epoch, fields[2])
580: 	}
581: 
582: 	modularitylabel := ""
583: 	if len(fields) == 6 && fields[5] != "(none)" {
584: 		modularitylabel = fields[5]
585: 	}
586: 
587: 	return &models.Package{
588: 		Name:            fields[0],
589: 		Version:         ver,
590: 		Release:         fields[3],
591: 		Arch:            fields[4],
592: 		ModularityLabel: modularitylabel,
593: 	}, nil
594: }
