596: func (o *redhatBase) parseInstalledPackagesLineFromRepoquery(line string) (*models.Package, error) {
597: 	fields := strings.Fields(line)
598: 	if len(fields) != 6 {
599: 		return nil, xerrors.Errorf("Failed to parse package line: %s", line)
600: 	}
601: 
602: 	ver := ""
603: 	epoch := fields[1]
604: 	if epoch == "0" || epoch == "(none)" {
605: 		ver = fields[2]
606: 	} else {
607: 		ver = fmt.Sprintf("%s:%s", epoch, fields[2])
608: 	}
609: 
610: 	repo := strings.TrimPrefix(fields[5], "@")
611: 	if repo == "installed" {
612: 		repo = "amzn2-core"
613: 	}
614: 
615: 	return &models.Package{
616: 		Name:       fields[0],
617: 		Version:    ver,
618: 		Release:    fields[3],
619: 		Arch:       fields[4],
620: 		Repository: repo,
621: 	}, nil
622: }
