624: func (o *redhatBase) parseRpmQfLine(line string) (pkg *models.Package, ignored bool, err error) {
625: 	for _, suffix := range []string{
626: 		"Permission denied",
627: 		"is not owned by any package",
628: 		"No such file or directory",
629: 	} {
630: 		if strings.HasSuffix(line, suffix) {
631: 			return nil, true, nil
632: 		}
633: 	}
634: 	pkg, err = o.parseInstalledPackagesLine(line)
635: 	return pkg, false, err
636: }
