647: func (o *redhatBase) scanUpdatablePackages() (models.Packages, error) {
648: 	isDnf := o.exec(util.PrependProxyEnv(`repoquery --version | grep dnf`), o.sudo.repoquery()).isSuccess()
649: 	cmd := `repoquery --all --pkgnarrow=updates --qf='%{NAME} %{EPOCH} %{VERSION} %{RELEASE} %{REPO}'`
650: 	if isDnf {
651: 		cmd = `repoquery --upgrades --qf='%{NAME} %{EPOCH} %{VERSION} %{RELEASE} %{REPONAME}' -q`
652: 	}
653: 	for _, repo := range o.getServerInfo().Enablerepo {
654: 		cmd += " --enablerepo=" + repo
655: 	}
656: 
657: 	r := o.exec(util.PrependProxyEnv(cmd), o.sudo.repoquery())
658: 	if !r.isSuccess() {
659: 		return nil, xerrors.Errorf("Failed to SSH: %s", r)
660: 	}
661: 
662: 	// Collect Updatable packages, installed, candidate version and repository.
663: 	return o.parseUpdatablePacksLines(r.Stdout)
664: }
