666: // parseUpdatablePacksLines parse the stdout of repoquery to get package name, candidate version
667: func (o *redhatBase) parseUpdatablePacksLines(stdout string) (models.Packages, error) {
668: 	updatable := models.Packages{}
669: 	lines := strings.Split(stdout, "\n")
670: 	for _, line := range lines {
671: 		if len(strings.TrimSpace(line)) == 0 {
672: 			continue
673: 		} else if strings.HasPrefix(line, "Loading") {
674: 			continue
675: 		}
676: 		pack, err := o.parseUpdatablePacksLine(line)
677: 		if err != nil {
678: 			return updatable, err
679: 		}
680: 		updatable[pack.Name] = pack
681: 	}
682: 	return updatable, nil
683: }
