689: 	}
690: 
691: 	ver := ""
692: 	epoch := fields[1]
693: 	if epoch == "0" {
694: 		ver = fields[2]
695: 	} else {
696: 		ver = fmt.Sprintf("%s:%s", epoch, fields[2])
697: 	}
698: 
699: 	repos := strings.Join(fields[4:], " ")
700: 
701: 	p := models.Package{
702: 		Name:       fields[0],
703: 		NewVersion: ver,
704: 		NewRelease: fields[3],
705: 		Repository: repos,
706: 	}
707: 	return p, nil
708: }
