718: func (o *redhatBase) isExecNeedsRestarting() bool {
719: 	switch o.Distro.Family {
720: 	case constant.OpenSUSE, constant.OpenSUSELeap, constant.SUSEEnterpriseServer, constant.SUSEEnterpriseDesktop:
721: 		if o.getServerInfo().Mode.IsOffline() {
722: 			return false
723: 		} else if o.getServerInfo().Mode.IsFastRoot() || o.getServerInfo().Mode.IsDeep() {
724: 			return true
725: 		}
726: 		return false
727: 	case constant.RedHat, constant.CentOS, constant.Alma, constant.Rocky, constant.Oracle:
728: 		majorVersion, err := o.Distro.MajorVersion()
729: 		if err != nil || majorVersion < 6 {
730: 			o.log.Errorf("Not implemented yet: %s, err: %+v", o.Distro, err)
731: 			return false
732: 		}
733: 
734: 		if o.getServerInfo().Mode.IsOffline() {
735: 			return false
736: 		} else if o.getServerInfo().Mode.IsFastRoot() || o.getServerInfo().Mode.IsDeep() {
737: 			return true
738: 		}
739: 		return false
740: 	case constant.Fedora:
741: 		majorVersion, err := o.Distro.MajorVersion()
742: 		if err != nil || majorVersion < 13 {
743: 			o.log.Errorf("Not implemented yet: %s, err: %+v", o.Distro, err)
744: 			return false
745: 		}
746: 
747: 		if o.getServerInfo().Mode.IsOffline() {
748: 			return false
749: 		} else if o.getServerInfo().Mode.IsFastRoot() ||
750: 			o.getServerInfo().Mode.IsDeep() {
751: 			return true
752: 		}
753: 		return false
754: 	}
755: 
756: 	return !o.getServerInfo().Mode.IsFast()
757: }
