}", "new_string": "func isRunningKernel(pack models.Package, family string, release string, kernel models.Kernel) (isKernel, running bool) {
	switch family {
	case constant.OpenSUSE, constant.OpenSUSELeap, constant.SUSEEnterpriseServer, constant.SUSEEnterpriseDesktop:
		if pack.Name == "kernel-default" {
			// Remove the last period and later because uname don't show that.
			ss := strings.Split(pack.Release, ".")
			rel := strings.Join(ss[0:len(ss)-1], ".")
			ver := fmt.Sprintf("%s-%s-default", pack.Version, rel)
			return true, kernel.Release == ver
		}
		return false, false

	case constant.RedHat, constant.Oracle, constant.CentOS, constant.Alma, constant.Rocky, constant.Amazon, constant.Fedora:
		// Kernel adjacent packages (kernel-tools, kernel-srpm-macros, perf, ...)
		// are not kernel packages, they must not be filtered out.
		if !isKernelPackage(pack.Name) {
			return false, false
		}
		return true, kernel.Release == runningKernelRelease(pack, family, release)

	default:
		logging.Log.Warnf("Reboot required is not implemented yet: %s, %v", family, kernel)
	}
	return false, false
}

// isKernelPackage returns whether the package is a kernel image, kernel module
// or kernel devel package. Packages that only have the `kernel-` prefix
// (e.g. kernel-tools, kernel-livepatch-*, kernel-srpm-macros) are not kernel packages.
func isKernelPackage(name string) bool {
	if name == "kernel" {
		return true
	}
	for _, prefix := range []string{
		"kernel-core",
		"kernel-modules",
		"kernel-devel",
		"kernel-debug",
		"kernel-rt",
		"kernel-uek",
	} {
		if strings.HasPrefix(name, prefix) {
			return true
		}
	}
	return false
}

// isDebugKernelPackage returns whether the kernel package is a debug variant.
func isDebugKernelPackage(name string) bool {
	return strings.Contains(name, "debug")
}

// runningKernelRelease builds the kernel release string (`uname -r`) that the
// given kernel package would produce when it is the running kernel.
// The format depends on the OS family and the distribution release.
func runningKernelRelease(pack models.Package, family string, release string) string {
	if archSuffixedKernelRelease(family, release) {
		// RHEL 6+, AlmaLinux, RockyLinux, Amazon Linux, Fedora 9+
		// e.g. 5.14.0-427.13.1.el9_4.x86_64, 5.14.0-427.13.1.el9_4.x86_64+debug
		ver := fmt.Sprintf("%s-%s.%s", pack.Version, pack.Release, pack.Arch)
		if isDebugKernelPackage(pack.Name) {
			ver += "+debug"
		}
		return ver
	}
	// RHEL, CentOS and Oracle Linux older than 6, Fedora older than 9
	// e.g. 2.6.32-754.el6, 2.6.32-754.el6debug
	ver := fmt.Sprintf("%s-%s", pack.Version, pack.Release)
	if isDebugKernelPackage(pack.Name) {
		ver += "debug"
	}
	return ver
}

// archSuffixedKernelRelease returns whether the distribution kernel release
// string has the architecture suffix (modern) or not (legacy).
func archSuffixedKernelRelease(family string, release string) bool {
	switch family {
	case constant.Alma, constant.Rocky, constant.Amazon:
		return true
	}

	major, err := config.Distro{Family: family, Release: release}.MajorVersion()
	if err != nil {
		// unknown release format, assume the modern format
		return true
	}

	switch family {
	case constant.Fedora:
		return major >= 9
	default: // RedHat, CentOS, Oracle and the other RedHat based distributions
		return major >= 6
	}
}"}

